.darma-loader-darma-b9-double-helix-ribbon { --accent: var(--loader-color, #2dd4bf); --accent-2: var(--loader-secondary-color, #f472b6); width: var(--loader-size, 100px); height: calc(var(--loader-size, 100px) * .5); display: flex; align-items: center; justify-content: space-between; }
.darma-loader-darma-b9-double-helix-ribbon span { position: relative; width: calc(var(--loader-size, 100px) * .07); height: 100%; }
.darma-loader-darma-b9-double-helix-ribbon span::before, .darma-loader-darma-b9-double-helix-ribbon span::after { content: ''; position: absolute; left: 0; width: 100%; aspect-ratio: 1; border-radius: 50%; }
.darma-loader-darma-b9-double-helix-ribbon span::before { background: var(--accent); animation: darma-loader-darma-b9-double-helix-ribbon-helix-a calc(var(--loader-speed, 1s) * 1.6) ease-in-out infinite; }
.darma-loader-darma-b9-double-helix-ribbon span::after { background: var(--accent-2); animation: darma-loader-darma-b9-double-helix-ribbon-helix-b calc(var(--loader-speed, 1s) * 1.6) ease-in-out infinite; }
.darma-loader-darma-b9-double-helix-ribbon span:nth-child(1) { animation-delay: 0s; } .darma-loader-darma-b9-double-helix-ribbon span:nth-child(1)::before, .darma-loader-darma-b9-double-helix-ribbon span:nth-child(1)::after { animation-delay: 0s; }
.darma-loader-darma-b9-double-helix-ribbon span:nth-child(2)::before, .darma-loader-darma-b9-double-helix-ribbon span:nth-child(2)::after { animation-delay: calc(var(--loader-speed, 1s) * .18); }
.darma-loader-darma-b9-double-helix-ribbon span:nth-child(3)::before, .darma-loader-darma-b9-double-helix-ribbon span:nth-child(3)::after { animation-delay: calc(var(--loader-speed, 1s) * .36); }
.darma-loader-darma-b9-double-helix-ribbon span:nth-child(4)::before, .darma-loader-darma-b9-double-helix-ribbon span:nth-child(4)::after { animation-delay: calc(var(--loader-speed, 1s) * .54); }
.darma-loader-darma-b9-double-helix-ribbon span:nth-child(5)::before, .darma-loader-darma-b9-double-helix-ribbon span:nth-child(5)::after { animation-delay: calc(var(--loader-speed, 1s) * .72); }
.darma-loader-darma-b9-double-helix-ribbon span:nth-child(6)::before, .darma-loader-darma-b9-double-helix-ribbon span:nth-child(6)::after { animation-delay: calc(var(--loader-speed, 1s) * .9); }
.darma-loader-darma-b9-double-helix-ribbon span:nth-child(7)::before, .darma-loader-darma-b9-double-helix-ribbon span:nth-child(7)::after { animation-delay: calc(var(--loader-speed, 1s) * 1.08); }
.darma-loader-darma-b9-double-helix-ribbon span:nth-child(8)::before, .darma-loader-darma-b9-double-helix-ribbon span:nth-child(8)::after { animation-delay: calc(var(--loader-speed, 1s) * 1.26); }
@keyframes darma-loader-darma-b9-double-helix-ribbon-helix-a { 0%, 100% { top: 0; transform: scale(.55); z-index: 1; } 50% { top: calc(100% - var(--loader-size, 100px) * .07); transform: scale(1); z-index: 3; } }
@keyframes darma-loader-darma-b9-double-helix-ribbon-helix-b { 0%, 100% { top: calc(100% - var(--loader-size, 100px) * .07); transform: scale(1); z-index: 3; } 50% { top: 0; transform: scale(.55); z-index: 1; } }

